import type { Category } from "./categories";

/**
 * Seed data: 1152 globally diverse foods grouped into categories, each with
 * names in TR / EN / DE / ES / FR. Glycemic load is computed at insert time as
 * round(GI * carb_100g / 100), so we only store carb & GI here.
 *
 * Values are nutrition-table approximations (per 100 g) for informational
 * estimation only, not a medical reference.
 *
 * `gi` is 0 wherever no established figure exists, and for anything essentially
 * carb-free where the number would mean nothing. Zero is the honest answer, not
 * a low glycemic index: it is never shown as one and never enters an estimate,
 * since glycemic load is GI x carbs and the calculator works from carbs alone.
 *
 * ADDING FOODS: the name has to be unique WITHIN each language column across the
 * whole array, because that is the key the top-up matches on (see ./seedVersion
 * and syncSeedCatalog in ./index) and because two identical rows in one list is
 * a bug the user sees. scripts/seed.test.ts enforces that, the value ranges and
 * the character rules. Bump SEED_CATALOG_VERSION or the new foods only ever
 * reach fresh installs.
 */
export interface SeedFood {
  cat: Category;
  tr: string;
  en: string;
  de: string;
  es: string;
  fr: string;
  /** carbohydrate grams per 100 g */
  carb: number;
  /** glycemic index (glucose = 100) */
  gi: number;
  /** typical single-serving size in grams (defaults to 100) */
  portion?: number;
}

